"""Differential test: structured generator + independent reference model for sections 4-6."""
import random, hashlib, json
from harness import run, hx, envelope

ACCOUNTS = [
    {'id': 'alice', 'default': 'sip:alice@lab.test',
     'aliases': ['sip:alice@lab.test', 'sip:desk@lab.test', 'tel:+12025550100']},
    {'id': 'bob', 'default': 'sips:bob@lab.test',
     'aliases': ['sips:bob@lab.test', 'sip:bob2@lab.test', 'tel:+442071234567']},
]
ALIAS = {}
DEFAULT = {}
for a in ACCOUNTS:
    DEFAULT[a['id']] = a['default']
    for u in a['aliases']:
        ALIAS[u] = a['id']
ANON = 'sip:anonymous@anonymous.invalid'
PEERS = [{'id': 'edge', 'mode': 'access', 'accounts': []},
         {'id': 'r_alice', 'mode': 'relay', 'accounts': ['alice']},
         {'id': 'r_both', 'mode': 'relay', 'accounts': ['alice', 'bob']},
         {'id': 'r_none', 'mode': 'relay', 'accounts': []}]
PEER_ACC = {p['id']: set(p['accounts']) for p in PEERS}
PEER_MODE = {p['id']: p['mode'] for p in PEERS}
OTHER = ['sip:evil@other.test', 'tel:+999', 'sip:alice@lab.test:5060']


def gen_spec(rng):
    peer = rng.choice([p['id'] for p in PEERS])
    mode = PEER_MODE[peer]
    auth = None if mode == 'relay' else rng.choice([a['id'] for a in ACCOUNTS] + [None])
    egress = rng.choice(['internal', 'external'])
    privacy = rng.choice(['absent', 'id', 'none', 'id', 'none', 'absent'])
    has_ppi = rng.random() < 0.5
    has_pai = rng.random() < 0.5
    pool = list(ALIAS) + OTHER
    def mklist():
        k = rng.choice([1, 1, 2])
        if k == 1:
            return [rng.choice(pool)]
        a = rng.choice([u for u in pool if not u.startswith('tel:')])
        b = rng.choice([u for u in pool if u.startswith('tel:')])
        lst = [a, b]
        rng.shuffle(lst)
        return lst
    ppi = mklist() if has_ppi else None
    pai = mklist() if has_pai else None
    acct_pool = list(ALIAS) + [ANON] + OTHER
    from_uri = rng.choice(acct_pool)
    tag = rng.choice(['t1', 't2', 'xyz'])
    call_id = rng.choice(['c1', 'c2', 'c3'])
    cseq = rng.choice([1, 1, 2, 7])
    method = rng.choice(['MESSAGE', 'INVITE'])
    body = rng.choice([b'', b'a', b'bb', b'abc'])
    target = rng.choice(['sip:bob@lab.test', 'sip:someone@else.test'])
    return dict(peer=peer, mode=mode, auth=auth, egress=egress, privacy=privacy, ppi=ppi, pai=pai,
                from_uri=from_uri, tag=tag, call_id=call_id, cseq=cseq, method=method, body=body,
                target=target)


def to_wire(s):
    lines = ['%s %s SIP/2.0' % (s['method'], s['target'])]
    lines.append('From: <%s>;tag=%s' % (s['from_uri'], s['tag']))
    lines.append('To: <%s>' % s['target'])
    lines.append('Call-ID: %s' % s['call_id'])
    lines.append('CSeq: %d %s' % (s['cseq'], s['method']))
    if s['pai']:
        lines.append('P-Asserted-Identity: ' + ', '.join('<%s>' % u for u in s['pai']))
    if s['ppi']:
        lines.append('P-Preferred-Identity: ' + ', '.join('<%s>' % u for u in s['ppi']))
    if s['privacy'] != 'absent':
        lines.append('Privacy: %s' % s['privacy'])
    lines.append('Content-Length: %d' % len(s['body']))
    return ('\r\n'.join(lines) + '\r\n\r\n').encode() + s['body']


def order(lst):
    """canonical ordering: sip/sips first, tel second; validate structure"""
    if lst is None:
        return None
    if len(lst) == 1:
        return list(lst)
    kinds = [u.startswith('tel:') for u in lst]
    if kinds[0] == kinds[1]:
        return 'BAD'
    return [lst[1], lst[0]] if kinds[0] else list(lst)


def reference(specs, ttl, cap):
    """Independent model of sections 4-6."""
    ledger = {}   # key -> (commit, first_index, insert_time)
    results = []
    for idx, s in enumerate(specs):
        t = s['t']
        for k in list(ledger):
            if t >= ledger[k][2] + ttl:
                del ledger[k]
        # structural field validity
        pai = order(s['pai']); ppi = order(s['ppi'])
        if pai == 'BAD' or ppi == 'BAD':
            results.append({'index': idx, 'decision': 'reject', 'reason': 'fields'}); continue
        for u in (pai or []) + (ppi or []):
            c, _ = canon(u)
            if c is None:
                results.append({'index': idx, 'decision': 'reject', 'reason': 'fields'}); break
        else:
            if s['auth'] is None and s['mode'] == 'access':
                results.append({'index': idx, 'decision': 'reject', 'reason': 'auth'}); continue
            acct = None; sel = None; asserted = None
            if s['mode'] == 'access':
                acct = s['auth']
                if ppi is not None:
                    if any(ALIAS.get(canon(u)[0]) != acct for u in ppi):
                        results.append({'index': idx, 'decision': 'reject', 'reason': 'identity'}); continue
                    asserted = [canon(u)[0] for u in ppi]
                    sel = asserted[0]
                else:
                    sel = DEFAULT[acct]; asserted = [sel]
            else:
                if ppi is not None or pai is None:
                    results.append({'index': idx, 'decision': 'reject', 'reason': 'identity'}); continue
                owners = set()
                ok = True
                for u in pai:
                    o = ALIAS.get(canon(u)[0])
                    if o is None:
                        ok = False; break
                    owners.add(o)
                if not ok or len(owners) != 1:
                    results.append({'index': idx, 'decision': 'reject', 'reason': 'identity'}); continue
                acct = owners.pop()
                if acct not in PEER_ACC[s['peer']]:
                    results.append({'index': idx, 'decision': 'reject', 'reason': 'identity'}); continue
                asserted = [canon(u)[0] for u in pai]
                sel = asserted[0]
            fc, _ = canon(s['from_uri'])
            if fc is None:
                results.append({'index': idx, 'decision': 'reject', 'reason': 'fields'}); continue
            if fc == ANON:
                if s['privacy'] != 'id':
                    results.append({'index': idx, 'decision': 'reject', 'reason': 'identity'}); continue
            elif ALIAS.get(fc) != acct:
                results.append({'index': idx, 'decision': 'reject', 'reason': 'identity'}); continue
            out_from = ANON if s['privacy'] == 'id' else sel
            out_pai = [] if (s['egress'] == 'external' and s['privacy'] != 'none') else list(asserted)
            tc, _ = canon(s['target'])
            key = (s['peer'], s['call_id'], s['cseq'], s['method'])
            commit = (acct, sel, tuple(asserted), fc, s['tag'], tc, s['privacy'], s['egress'], s['body'])
            ent = ledger.get(key)
            rec = {'index': idx, 'account': acct, 'identity': sel, 'from': out_from, 'pai': out_pai,
                   'method': s['method'], 'target': tc, 'call_id': s['call_id'], 'cseq': s['cseq'],
                   'tag': s['tag'], 'privacy': s['privacy'],
                   'body_sha256': hashlib.sha256(s['body']).hexdigest()}
            if ent is None:
                if len(ledger) >= cap:
                    oldest = min(ledger, key=lambda k: ledger[k][1])
                    del ledger[oldest]
                ledger[key] = (commit, idx, t)
                rec.update(decision='accept', first=idx)
            elif ent[0] == commit:
                rec.update(decision='replay', first=ent[1])
            else:
                results.append({'index': idx, 'decision': 'reject', 'reason': 'conflict'}); continue
            results.append(rec)
    ordered = []
    for r in results:
        ordered.append(r)
    return {'results': ordered,
            'accepted': sum(1 for r in results if r.get('decision') == 'accept'),
            'replayed': sum(1 for r in results if r.get('decision') == 'replay'),
            'rejected': sum(1 for r in results if r['decision'] == 'reject'),
            'live': len(ledger)}


def canon(u):
    """minimal canonicalizer for the generator's URI pool"""
    if u.startswith('tel:'):
        d = ''.join(c for c in u[4:] if c.isdigit())
        return ('tel:+' + d, True) if 3 <= len(d) <= 15 else (None, False)
    for p in ('sips:', 'sip:'):
        if u.lower().startswith(p):
            rest = u[p.index(':') + 1:]
            if '@' not in rest:
                return (None, False)
            user, hp = rest.split('@', 1)
            host = hp.split(':')[0]
            port = hp[len(host) + 1:] if ':' in hp else ''
            out = p[:-1].lower() + ':' + user + '@' + host.lower() + ((':' + str(int(port))) if port else '')
            return (out, False)
    return (None, False)


rng = random.Random(99)
mismatch = 0
for trial in range(30):
    n = rng.randint(20, 120)
    specs = []
    t = 0
    events = []
    for i in range(n):
        s = gen_spec(rng)
        t += rng.choice([0, 0, 1, 5, 40])
        s['t'] = t
        specs.append(s)
        events.append({'t': t, 'peer': s['peer'], 'auth': s['auth'], 'egress': s['egress'],
                       'wire_hex': hx(to_wire(s))})
    ttl = rng.choice([1, 10, 100, 1000])
    cap = rng.choice([1, 2, 5, 50])
    doc = envelope(events, accounts=ACCOUNTS, peers=PEERS, ttl=ttl, cap=cap)
    got = run(doc)
    want = reference(specs, ttl, cap)
    if got != want:
        mismatch += 1
        print('MISMATCH trial', trial, 'ttl', ttl, 'cap', cap)
        for a, b in zip(got['results'], want['results']):
            if a != b:
                print('  got ', json.dumps(a, sort_keys=True))
                print('  want', json.dumps(b, sort_keys=True))
                break
        for k in ('accepted', 'replayed', 'rejected', 'live'):
            if got[k] != want[k]:
                print('  count', k, got[k], want[k])
        if mismatch > 2:
            break
print('diff trials done, mismatches:', mismatch)
